uint32_t crc = 0;
const uint8_t* buf = reinterpret_cast<const uint8_t*>(data);
const uint8_t* end = buf + n;

// Process byte-by-byte until aligned to 8 bytes
while (reinterpret_cast<uintptr_t>(buf) % 8 != 0 && buf < end) {
    crc = kByteExtensionTable[(crc ^ *buf++) & 0xff] ^ (crc >> 8);
}

// Process 8 bytes at a time
while (buf + 8 <= end) {
    crc ^= *reinterpret_cast<const uint32_t*>(buf);
    uint32_t high = *reinterpret_cast<const uint32_t*>(buf + 4);
    crc = kStrideExtensionTable0[crc & 0xff] ^
          kStrideExtensionTable1[(crc >> 8) & 0xff] ^
          kStrideExtensionTable0[(high >> 16) & 0xff] ^
          kStrideExtensionTable1[(high >> 24) & 0xff] ^
          kStrideExtensionTable0[(crc >> 16) & 0xff] ^
          kStrideExtensionTable1[(high >> 8) & 0xff] ^
          kStrideExtensionTable0[high & 0xff] ^
          kStrideExtensionTable1[(crc >> 24) & 0xff];
    buf += 8;
}

// Process remaining bytes
while (buf < end) {
    crc = kByteExtensionTable[(crc ^ *buf++) & 0xff] ^ (crc >> 8);
}

return crc;

